package com.jnapanam.sportszone.training.controller;import com.jnapanam.sportszone.training.dto.*;import com.jnapanam.sportszone.training.service.TrainingService;import jakarta.validation.Valid;import java.util.*;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/v1/training")public class CustomerTrainingController{private final TrainingService s;public CustomerTrainingController(TrainingService s){this.s=s;}@PostMapping("/batches/{batchId}/enrollments")@ResponseStatus(HttpStatus.CREATED)public EnrollmentResponse enroll(Authentication a,@PathVariable UUID batchId,@Valid@RequestBody EnrollmentRequest r){return s.enroll(id(a),batchId,r);}@GetMapping("/enrollments/me")public List<EnrollmentResponse>mine(Authentication a){return s.mine(id(a));}@PostMapping("/enrollments/{id}/cancel")public EnrollmentResponse cancel(Authentication a,@PathVariable UUID id){return s.cancel(id(a),id);}private static UUID id(Authentication a){return UUID.fromString(a.getName());}}
